-- ========================================================




-- ========================================================

function DebugBoxRestartButton:__init()
    self.controller = nil
    self.co_1 = nil
end


function DebugBoxRestartButton:__delete()
    if self.co_1 ~= nil then
        cs_coroutine.stop(self.co_1)
    end
    self.co_1 = nil
end



function DebugBoxRestartButton:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end



function DebugBoxRestartButton:Init(debugBox_, restartButton_)

    self.isDoing = false

    self.debugBox = debugBox_    -- DebugBox
    self.restartButton = restartButton_ -- Button

    self.restartButton.onClick:AddListener(function ()
        self:OnPress()
    end)

    self.initMorphologyTypeStr = GlobalsInDreamSpace.GetStringState("MorphologyType") -- string 版 RoleMorphologyType
    assert(self.initMorphologyTypeStr == "Cat" or self.initMorphologyTypeStr == "Human")

    self.initPos = self.debugBox.vTargetFollow.position -- Vector3

    print("koko - debugBox - RestartButton 初始化完成")
end




function DebugBoxRestartButton:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


function DebugBoxRestartButton:OnPress()
    if self.isDoing == false then
        DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
        self.co_1 = cs_coroutine.start(function()
            self:Restart()
        end) 

    end
end


-- ret: IEnumerator
function DebugBoxRestartButton:Restart()
    
    self.isDoing = true

    local moveOffset = self.debugBox.vTargetFollow.position - self.initPos

    self.debugBox.humanMotor.enabled = false
    self.debugBox.catMotor.enabled = false

    self.debugBox.humanCharacter.transform.position = self.debugBox.humanCharacter.transform.position - moveOffset
    self.debugBox.catCharacter.transform.position = self.debugBox.catCharacter.transform.position - moveOffset

    local currentMorphologyType = GlobalsInDreamSpace.GetStringState("MorphologyType")
    assert(currentMorphologyType ~= "")

    -- todo: temporarily not use switchablePlayerController
    if currentMorphologyType ~= self.initMorphologyTypeStr then
        self.debugBox.switchablePlayerController:Switch(false)
    end

    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 2 ))

    self.debugBox.humanMotor.enabled = true
    self.debugBox.catMotor.enabled = true

    -----:
    -- for i, e in ipairs(self.debugBox.restarts) do
    --     e:Restart()
    -- end
    -- for i, e in ipairs(self.debugBox.restarts) do
    --     while e:IsRestartFinished() == false do
    --         coroutine.yield(Yielders.EndOfFrame)
    --     end
    -- end
    -----:
    self.isDoing = false
end




return DebugBoxRestartButton

